param(
    [string]$Configuration = 'Release',
    [switch]$Force,

    [string[]]$Address = @()
)

$ErrorActionPreference = 'Stop'
$rebuildRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
$vcRoot = 'D:\Tools\vc71'
# Alternate 13.10.4035 QFE toolset (WinDDK 3790.1830). Entries tagged Compiler='qfe4035'
# (~11 retail objects RTM 3077 cannot reproduce) compile with this cl.exe; headers/libs stay
# RTM. Override with $env:VC71_QFE. See docs/pipeline/QFE4035_COMPILER_GATE.md.
$vcQfeRoot = if ($env:VC71_QFE) { $env:VC71_QFE } else { 'D:\Tools\vc71-qfe4035' }
$sourceRoot = Join-Path $rebuildRoot 'src\compiled'
$outDir = Join-Path $rebuildRoot "build\candidates-$Configuration"
$reportDir = Join-Path $rebuildRoot 'compile-gate'
New-Item -ItemType Directory -Path $outDir -Force | Out-Null
New-Item -ItemType Directory -Path $reportDir -Force | Out-Null
$dependencyFiles = @(
    Get-ChildItem (Join-Path $rebuildRoot 'include') -File -Recurse -ErrorAction SilentlyContinue
    Get-ChildItem (Join-Path $rebuildRoot 'tests') -File -Filter '*.h' -Recurse -ErrorAction SilentlyContinue
)
$newestDependencyWrite = if ($dependencyFiles.Count -gt 0) {
    ($dependencyFiles | Sort-Object LastWriteTimeUtc -Descending | Select-Object -First 1).LastWriteTimeUtc
} else {
    [datetime]::MinValue
}

