$requestedAddresses = @(
    $Address |
        ForEach-Object {
            $_.Trim().ToLowerInvariant().Replace('0x', '')
        } |
        Where-Object { $_ }

)
if ($requestedAddresses.Count -gt 0) {
    $catalogAddresses = @(
        $catalog |
            ForEach-Object { $_.Address.ToLowerInvariant() }
    )
    $unknownAddresses = @(
        $requestedAddresses |
            Where-Object { $_ -notin $catalogAddresses }
    )
    if ($unknownAddresses.Count -gt 0) {
        throw (
            'Requested candidate addresses are not in the catalog: ' +
            ($unknownAddresses -join ', ')
        )
    }
    $catalog = @(
        $catalog |
            Where-Object {
                $_.Address.ToLowerInvariant() -in $requestedAddresses
            }
    )
}

$oldPath = $env:PATH
$oldInclude = $env:INCLUDE
$oldLib = $env:LIB
$results = @()
try {
    $env:PATH = "$(Join-Path $vcRoot 'bin');$oldPath"
    # Sharded tests can still share small harness headers kept at tests/.
    # Add that root explicitly because quoted includes otherwise search only the
    # test's new address-shard directory.
    $env:INCLUDE = "$(Join-Path $vcRoot 'include');$(Join-Path $rebuildRoot 'include');$(Join-Path $rebuildRoot 'tests')"
    $env:LIB = Join-Path $vcRoot 'lib'

    foreach ($entry in $catalog) {
        $source = Join-Path $sourceRoot $entry.Source
        $addressKey = $entry.Address.ToLowerInvariant()
        $functionOutDir = Join-Path $outDir (
            Join-Path $addressKey.Substring(0, 2) (
                Join-Path $addressKey.Substring(2, 2) $addressKey
            )
        )
        New-Item -ItemType Directory -Path $functionOutDir -Force | Out-Null
        $object = Join-Path $functionOutDir "$($entry.Address).obj"
        $log = Join-Path $functionOutDir "$($entry.Address).compile.log"
        $testSource = Join-Path (Join-Path $rebuildRoot 'tests') $entry.TestSource
        $testObject = Join-Path $functionOutDir "$($entry.Address).test.obj"
        $testCompileLog = Join-Path $functionOutDir "$($entry.Address).test-compile.log"
        $testExe = Join-Path $functionOutDir "$($entry.Address).test.exe"
        $testRunLog = Join-Path $functionOutDir "$($entry.Address).test-run.log"
        $cacheValid = -not $Force -and
            (Test-Path -LiteralPath $object) -and
            (Test-Path -LiteralPath $testRunLog) -and
            (Get-Item -LiteralPath $object).LastWriteTimeUtc -ge (Get-Item -LiteralPath $source).LastWriteTimeUtc -and
            (Get-Item -LiteralPath $object).LastWriteTimeUtc -ge $newestDependencyWrite -and
            (Get-Item -LiteralPath $testRunLog).LastWriteTimeUtc -ge (Get-Item -LiteralPath $testSource).LastWriteTimeUtc -and
            (Get-Item -LiteralPath $testRunLog).LastWriteTimeUtc -ge $newestDependencyWrite -and
            ((Get-Content -LiteralPath $testRunLog -Raw) -match $entry.PassPattern)
        if ($cacheValid) {
            $results += [pscustomobject]@{
                address = $entry.Address
                module = $entry.Module
                compiler = 'Microsoft Visual C++ 7.1'
                status = 'PASS'
                behavior_test = 'PASS'
                source = $source
                object = $object
                log = $log
                test_log = $testRunLog
            }
            continue
        }
        Remove-Item -LiteralPath $object -Force -ErrorAction SilentlyContinue
        # Per-entry compiler flags: retail was built by VC7.1 QFE 4035 whose /GS and
        # aliasing (/Oa) codegen differs from our RTM 3077. A few functions only reach
        # byte-parity with those extra flags; the catalog records them per-entry so the
        # build reproduces the exact retail bytes. Default stays /O2 /Oy /W3.
        $entryFlags = if ($entry.PSObject.Properties['CompilerFlags'] -and $entry.CompilerFlags) {
            $entry.CompilerFlags -split '\s+'
        } else { @('/O2','/Oy','/W3') }
        # Entries tagged Compiler='qfe4035' need the 13.10.4035 backend to reproduce their bytes.
        $entryCompilerRoot = if ($entry.PSObject.Properties['Compiler'] -and $entry.Compiler -eq 'qfe4035') {
            if (-not (Test-Path -LiteralPath (Join-Path $vcQfeRoot 'bin\cl.exe'))) {
                throw "Entry $($entry.Address) needs the QFE-4035 toolset but $vcQfeRoot\bin\cl.exe is missing (see docs/pipeline/QFE4035_COMPILER_GATE.md)"
            }
            $vcQfeRoot
        } else { $vcRoot }
        $output = & (Join-Path $entryCompilerRoot 'bin\cl.exe') /nologo /c @entryFlags /Fo$object $source 2>&1
        $exitCode = $LASTEXITCODE
        $output | Set-Content -LiteralPath $log -Encoding UTF8
        $passed = $exitCode -eq 0 -and (Test-Path -LiteralPath $object)
        Remove-Item -LiteralPath $testObject -Force -ErrorAction SilentlyContinue
        Remove-Item -LiteralPath $testExe -Force -ErrorAction SilentlyContinue
        $testOutput = & (Join-Path $vcRoot 'bin\cl.exe') /nologo /c /Od /W3 /Fo$testObject $testSource 2>&1
        $testCompileExit = $LASTEXITCODE
        $testOutput | Set-Content -LiteralPath $testCompileLog -Encoding UTF8
        if ($testCompileExit -ne 0 -or -not (Test-Path -LiteralPath $testObject)) {
            throw "Candidate test compile failed: $($entry.Address)"
        }
        $linkObjects = if ($entry.PSObject.Properties['BehaviorTestSourceOnly'] -and $entry.BehaviorTestSourceOnly) {
            @($testObject)
        } else {
            @($object, $testObject)
        }
        $linkOutput = & (Join-Path $vcRoot 'bin\link.exe') /nologo /out:$testExe $linkObjects 2>&1
        $linkExit = $LASTEXITCODE
        $linkOutput | Add-Content -LiteralPath $testCompileLog -Encoding UTF8
        if ($linkExit -ne 0 -or -not (Test-Path -LiteralPath $testExe)) {
            # Older generated behavior tests are deliberately self-contained and
            # define the candidate body in the test TU. Prefer testing the real
            # source object, but fall back to a test-only link when source+test
            # collides on that duplicate symbol. This matches verify_and_land.py.
            Remove-Item -LiteralPath $testExe -Force -ErrorAction SilentlyContinue
            $fallbackOutput = & (Join-Path $vcRoot 'bin\link.exe') /nologo /out:$testExe $testObject 2>&1
            $fallbackExit = $LASTEXITCODE
            @('--- test-only fallback ---') + $fallbackOutput |
                Add-Content -LiteralPath $testCompileLog -Encoding UTF8
            if ($fallbackExit -ne 0 -or -not (Test-Path -LiteralPath $testExe)) {
                throw "Candidate test link failed: $($entry.Address)"
            }
        }
        $runOutput = & $testExe 2>&1
        $runExit = $LASTEXITCODE
        $runOutput | Set-Content -LiteralPath $testRunLog -Encoding UTF8
        $behaviorPassed = $runExit -eq 0 -and ($runOutput -match $entry.PassPattern)
        $results += [pscustomobject]@{
            address = $entry.Address
            module = $entry.Module
            compiler = 'Microsoft Visual C++ 7.1'
            status = if ($passed) { 'PASS' } else { 'FAIL' }
            behavior_test = if ($behaviorPassed) { 'PASS' } else { 'FAIL' }
            source = $source
            object = if ($passed) { $object } else { '' }
            log = $log
            test_log = $testRunLog
        }
        if (-not $passed) {
            throw "Candidate compile failed: $($entry.Address) $($entry.Source)"
        }
        if (-not $behaviorPassed) {
            throw "Candidate behavior test failed: $($entry.Address)"
        }
    }
} finally {
    $env:PATH = $oldPath
    $env:INCLUDE = $oldInclude
    $env:LIB = $oldLib
}

$report = Join-Path $reportDir 'vc71-compiled.tsv'
$reportResults = $results
if (
    $requestedAddresses.Count -gt 0 -and
    (Test-Path -LiteralPath $report)
) {
    $updatedByAddress = @{}
    foreach ($result in $results) {
        $updatedByAddress[$result.address.ToLowerInvariant()] = $result
    }
    $reportResults = @(
        foreach ($existing in Import-Csv -LiteralPath $report -Delimiter "`t") {
            $addressKey = $existing.address.ToLowerInvariant()
            if ($updatedByAddress.ContainsKey($addressKey)) {
                $updatedByAddress[$addressKey]
                $updatedByAddress.Remove($addressKey)
            } else {
                $existing
            }
        }
        foreach ($remaining in $updatedByAddress.Values) {
            $remaining
        }
    )
}
$reportResults |
    Export-Csv -LiteralPath "$report.tmp" `
        -Delimiter "`t" `
        -NoTypeInformation `
        -Encoding UTF8
Move-Item -LiteralPath "$report.tmp" -Destination $report -Force
Write-Output (
    "CANDIDATE_BUILD PASS objects=$($results.Count) " +
    "scope=$(if ($requestedAddresses.Count) { 'selected' } else { 'all' }) " +
    "out=$outDir"
)
